function peopleHTML(e){const owner=e.owner===user.id,open=!e.drawn&&!e.archived,organising=owner&&open,needed=Math.max(0,3-e.members.length),role=m=>[m.id===user.id&&'You',m.id===e.owner&&'Organiser'].filter(Boolean).join(', '),got=e.members.filter(m=>m.ready).length;
return `<section id="people"><div class="grid-head"><h2>People</h2><span class="muted num">${e.drawn?(got===e.members.length?'Everyone is ready':`${got} of ${e.members.length} are ready`):plural(e.members.length,'person','people')}</span></div><ol class="tickets">${e.members.map((m,i)=>{const ready=e.drawn&&m.ready;const self=m.id===user.id;return `<li class="tk ${hue(i)}${ready?' torn':''}"${self?' data-self':''}><div class="stub">${ready?`<span>${pad(i+1)}</span>`:pad(i+1)}</div><div class="main"><div class="who"><span class="name">${esc(m.name)}</span>${role(m)?`<span class="sub">${role(m)}</span>`:''}</div>${organising&&m.id!==user.id?`<button class="quiet" data-action="remove-member" data-id="${m.id}" aria-label="Remove ${esc(m.name)}">Remove</button>`:e.drawn?`<span class="gift">${ready?'Gift ready':'Not yet'}</span>`:''}</div>${self?tapePieces(e.id,ready):''}</li>`}).join('')}${open?Array.from({length:needed},(_,i)=>`<li class="tk open"><div class="stub">${pad(e.members.length+i+1)}</div><div class="main"><span class="name">Waiting for someone to join</span></div></li>`).join(''):''}</ol></section>`}
const units={day:['day','days'],week:['week','weeks'],month:['month','months']},unitMax={day:365,week:52,month:12};
const describe=r=>r.n===0?'on the day':r.n===1&&r.unit==='day'?'the day before':`${r.n} ${units[r.unit][r.n===1?0:1]} before`;
const summary=rs=>rs.length?rs.map(describe).join(', ').replace(/^./,c=>c.toUpperCase())+'.':'No reminders.';
let rowId=0;
function reminderRow(r={n:1,unit:'week'}){const id='rem'+(++rowId);return `<li class="rem-row"><input id="${id}" type="number" inputmode="numeric" required min="${r.unit==='day'?0:1}" max="${unitMax[r.unit]}" value="${r.n}" aria-label="How many"><select aria-label="Days, weeks or months">${Object.keys(units).map(u=>`<option value="${u}" ${u===r.unit?'selected':''}>${units[u][r.n===1?0:1]}</option>`).join('')}</select><span>before</span><button type="button" class="quiet" data-action="rem-remove">Remove<span class="visually-hidden"> this reminder</span></button></li>`}
function reminderEditor(target,list,label,save){return `<form class="rem-editor" data-form="reminders" data-target="${target}" aria-label="${label}">${errorBox()}<ul class="rem-rows">${list.map(reminderRow).join('')}</ul><p class="hint rem-empty" ${list.length?'hidden':''}>No reminders. Add one, or save to have none.</p><div class="buttons"><button type="button" class="secondary" data-action="rem-add">Add a reminder<span class="visually-hidden"> to ${label.toLowerCase()}</span></button><button>${save}</button><button type="button" class="quiet" data-action="rem-cancel">Cancel</button></div></form>`}
function readReminders(form){return [...form.querySelectorAll('.rem-row')].map(li=>({n:Number($('input',li).value),unit:$('select',li).value}))}
function accountRemindersHTML(){const own=user.ownReminders;return `<fieldset class="choices" id="account-reminders"><legend>Reminders</legend><label class="check"><input type="radio" name="reminder-source" value="organiser" ${own?'':'checked'}><span>Use each organiser’s choice</span></label><label class="check"><input type="radio" name="reminder-source" value="own" ${own?'checked':''}><span>Use my own in every exchange</span></label>${own?`<div class="nested">${reminderEditor('account',user.reminders,'Your reminders for every exchange','Save reminders')}</div>`:''}<p class="hint">You can also set reminders for one exchange on its page.</p></fieldset>`}
function refreshAccountReminders(focus){const s=$('#account-reminders');if(!s)return;s.outerHTML=accountRemindersHTML();if(focus)$(`input[name="${focus.name}"][value="${focus.value}"]`)?.focus()}
// Reminders read as a summary with one Change control; the editors only appear when asked for.
function remindersHTML(e){const owner=e.owner===user.id,custom=e.mine.source==='exchange',from=e.mine.source==='account'?'your usual reminders':owner?'your default':'the organiser’s choice',back=e.mine.source==='account'||(custom&&user.ownReminders)?'my usual reminders':owner?'my default':'the organiser’s choice';return `<section class="sheet" id="reminders"><h2>Email reminders</h2><p class="hint">Sent before the exchange date, once the exchange is locked in.${user.verified?'':' Confirm your email address to get them: see <a href="#account">Account</a>.'}</p><dl class="rem-summary">${owner?`<div><dt class="label">Everyone</dt><dd>${summary(e.reminders)}</dd></div>`:''}${owner&&!custom&&!e.ready&&e.mine.source!=='account'?'':`<div><dt class="label">You</dt><dd>${e.ready?'None. Your gift is ready.':custom?summary(e.mine.reminders):`${summary(e.mine.reminders)} <span class="muted">Same as ${from}.</span>`}</dd></div>`}</dl>${owner||!e.ready?`<details class="rem-change"><summary>Change reminders</summary><div class="rem-body">${owner?`<h3>Everyone</h3>${reminderEditor('default',e.reminders,'Default reminders for everyone','Save for everyone')}`:''}${e.ready?'':custom?`<h3>Just you</h3>${reminderEditor('mine',e.mine.reminders,'Your reminders for this exchange','Save my reminders')}<button class="quiet" data-action="reminders-default">Go back to ${back}</button>`:`<details class="rem-change rem-own"><summary>Use different reminders for me</summary>${reminderEditor('mine',e.mine.reminders,'Your reminders for this exchange','Save my reminders')}</details>`}</div></details>`:''}</section>`}
// Checkboxes stay enabled while saving: disabling one would drop keyboard focus. Extra clicks during a save are undone instead.
const saving=new Set();
function refreshReminders(focusSelector){const s=$('#reminders');if(!s)return;s.outerHTML=remindersHTML(current);if(focusSelector)$(focusSelector)?.focus()}
async function invite(code,version){sessionStorage.setItem('giftyInvite',code);const e=await api('invite/'+encodeURIComponent(code));if(version!==routeVersion)return;header();$('#main').innerHTML=`<div class="narrow"><h1>${esc(e.name)}</h1><p>${esc(e.organiser)} has invited you to join this gift exchange. Once the organiser locks it in, you’ll draw one person to buy for.</p><dl class="facts"><div><dt class="label">Date</dt><dd>${date(e.date)}</dd></div><div><dt class="label">Spending limit</dt><dd>${money(e)}</dd></div><div><dt class="label">Joined so far</dt><dd>${plural(e.people,'person','people')}</dd></div></dl>${user?`<form data-form="join">${errorBox()}<input type="hidden" name="code" value="${esc(code)}"><button class="full">Join as ${esc(user.name)}</button></form>`:'<div class="buttons"><a class="button" href="#signup">Create an account to join</a><a class="button secondary" href="#login">Sign in</a></div>'}</div>`}
function modal(title,content){clearToast();$('#dialog').innerHTML=`<h2 id="dialog-title">${title}</h2>${content}<button class="quiet close" data-action="close">Close</button>`;$('#dialog').showModal()}
function scopeField(w){if(!myExchanges.length)return '';const chosen=w.id?(w.exchanges||[]):wishScope?[wishScope]:[],all=!chosen.length;return `<fieldset class="choices"><legend>Who can see this idea</legend><label class="check"><input type="radio" name="scope" value="all" ${all?'checked':''}><span>Whoever is buying for me, in every exchange</span></label><label class="check"><input type="radio" name="scope" value="some" ${all?'':'checked'}><span>Only in these exchanges</span></label><div class="nested indent">${myExchanges.map(e=>`<label class="check"><input type="checkbox" name="exchanges" value="${e.id}" ${chosen.includes(e.id)?'checked':''}><span class="wrap">${esc(e.name)}</span></label>`).join('')}</div></fieldset>`}
function wishModal(w={}){modal(w.id?'Edit idea':'Add idea',`<form data-form="wish">${errorBox()}<input type="hidden" name="id" value="${esc(w.id||'')}">${field('title','What is it?','text',w.title||'','required maxlength="120" placeholder="e.g. Wool socks, size 6–8"')}${field('url','Link <span class="optional">(optional)</span>','url',w.url||'','maxlength="2000" placeholder="https://"')}<div class="field"><label for="note">Details <span class="optional">(optional)</span></label><textarea name="note" id="note" maxlength="1000" placeholder="Size, colour, where to buy it.">${esc(w.note||'')}</textarea></div>${scopeField(w)}<button class="full">Save</button></form>`)}
function confirmAction(title,body,action,id=''){modal(esc(title),`<p>${esc(body)}</p><form data-form="confirm" data-operation="${action}" data-id="${id}">${errorBox()}<div class="dialog-actions"><button type="button" class="secondary" data-action="close" autofocus>Cancel</button><button>${esc(title.replace(/\?$/,''))}</button></div></form>`)}
const done={'delete-wish':'Idea removed.',draw:'Locked in. Everyone can draw a name now.',archive:'Exchange archived.',leave:'You’ve left the exchange.',remove:'Person removed.',rotate:'Invitation link replaced. The old link no longer works.'};
function account(){header('account');$('#main').innerHTML=`<div class="narrow form-page"><h1>Account</h1><dl class="facts stacked"><div><dt class="label">Name</dt><dd class="wrap">${esc(user.name)}</dd></div><div><dt class="label">Email</dt><dd class="wrap">${esc(user.email)}</dd></div></dl>${mailOn?`<section class="sheet"><h2>Emails</h2>`+`${user.verified?'':'<p>Your email address isn’t confirmed yet. Gifty only sends exchange emails to confirmed addresses, so open the link in the confirmation email.</p><p><button class="secondary" data-action="resend-verify">Send the link again</button></p>'}<label class="check"><input type="checkbox" name="notify" ${user.notify?'checked':''}><span>Email me about my exchanges<span class="hint">When the exchange is locked in, and reminders before the exchange date. Emails never say who you’re buying for.</span></span></label>${accountRemindersHTML()}</section>`:''}<div class="after"><button class="secondary" data-action="logout">Sign out</button></div></div>`}
function forgot(){header('login');$('#main').innerHTML=`<div class="narrow"><h1>Reset your password</h1>${mailOn?`<p class="muted">Enter the email address you signed up with. If it has a Gifty account, you’ll get a link to choose a new password. The link works for one hour.</p><form class="sheet" data-form="forgot">${errorBox()}${field('email','Email address','email','','required maxlength="254" autocomplete="email"')}<button class="full">Send reset link</button></form>`:'<p>This Gifty server doesn’t send emails, so passwords can’t be reset here. Ask the person who runs it.</p>'}</div>`}
